#pragma once#include <stdio.h>class KTemporaryFile{  FILE *m_f;  char m_szPath[_MAX_PATH];public:  KTemporaryFile( LPCSTR pszPath, LPCSTR _Mode )  {    errno_t err = fopen_s( &m_f, pszPath, _Mode);    strcpy_s( m_szPath, pszPath );  }  ~KTemporaryFile()  {    Close();    remove( m_szPath );  }  void Close()  {    if( m_f )      fclose( m_f );    m_f = NULL;  }  operator FILE*()  {    return m_f;  }};class KFileLineReader{  FILE *m_file;public:  KFileLineReader() : m_file( NULL )  {}  KFileLineReader( FILE *file ) : m_file( file )  {}  void Assign( FILE *file )  {    m_file = file;  }  template<size_t _S>  bool GetLine( char (&bufOut)[_S] )  {    if( !m_file )      return false;    return fgets( bufOut, _S, m_file) ? true : false;  }  template<size_t _S>  bool GetLineEx( char (&bufOut)[_S] )  {    bool r = GetLine( bufOut) ? true : false;    if( !r )      return r;    size_t l = strlen( bufOut );    for( l; l>0; --l )    {      char &c = bufOut[l-1];      switch( c )      {      case '\r':      case '\n':        c = 0;        break;      default:        return r;      }    }    return r;  }};